'use strict';
const linkedinDefaults={query:'AI Engineer',location:'Bengaluru, Karnataka, India',posted:'week',remote:false,keywords:'Python, LLM, RAG, agents',exclude:'intern, internship, staff, principal, director',mode:'any',limit:100,pages:5};
let linkedinDraft=null,linkedinPoll=null,linkedinView='all';
function linkedinConfig(){return linkedinDraft||(linkedinDraft={...linkedinDefaults,...state.linkedin?.config,...(state.linkedin?.config&&!('pages' in state.linkedin.config)?{pages:5,limit:100}:{})})}
function linkedinSearchUrl(c){const p=new URLSearchParams({keywords:c.query,location:c.location,sortBy:'DD'});if(c.posted!=='any')p.set('f_TPR',{day:'r86400',week:'r604800',month:'r2592000'}[c.posted]);if(c.remote)p.set('f_WT','2');return 'https://www.linkedin.com/jobs/search/?'+p}
function renderLinkedin(){
const data=state.linkedin||{},c=linkedinConfig(),running=!!data.activity?.running,jobs=arr(data.jobs),shown=jobs.filter(j=>linkedinView==='all'||j.match_status===linkedinView),matches=jobs.filter(j=>j.match_status==='match').length;
$('#app').innerHTML=`<section class="narrow section"><span class="eyebrow">DISCOVER · MATCH · TRACK</span><h2>LinkedIn job search</h2><p>Search beyond the configured company boards, then match keywords locally. Your LinkedIn password and browser session are not needed for this public-search connection.</p><p class="notice">Public search snapshots may be incomplete. Each run follows up to your page limit, stops at your results cap, and scans up to ${esc(data.limits?.description_limit||8)} descriptions. Card-only results show uncertainty; keyword overlap is not a resume-fit score. Employer feeds and this search refresh separately.</p></section>
<form id="linkedin-form"><div class="toolbar"><label class="grow">Job search<input id="li-query" maxlength="160" value="${esc(c.query)}" placeholder="AI Engineer or Backend Engineer"></label><label class="grow">Location<input id="li-location" maxlength="160" value="${esc(c.location)}" placeholder="Bengaluru, Singapore, Germany…"></label><label>Posted<select id="li-posted">${Object.entries({day:'Past 24 hours',week:'Past week',month:'Past month',any:'Any time'}).map(([v,t])=>`<option value="${v}" ${c.posted===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Page limit<select id="li-pages">${[1,2,3,5,10].map(n=>`<option ${c.pages===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Results cap<select id="li-limit">${[10,25,50,100,250].map(n=>`<option ${c.limit===n?'selected':''}>${n}</option>`).join('')}</select></label></div>
<div class="toolbar"><label class="grow">Match keywords — comma-separated<input id="li-keywords" maxlength="400" value="${esc(c.keywords)}" placeholder="Python, RAG, Kafka"></label><label>Keyword rule<select id="li-mode"><option value="any" ${c.mode==='any'?'selected':''}>Any keyword</option><option value="all" ${c.mode==='all'?'selected':''}>All keywords</option></select></label><label class="grow">Exclude from job titles — comma-separated<input id="li-exclude" maxlength="300" value="${esc(c.exclude)}"></label><label class="checkline"><input id="li-remote" type="checkbox" ${c.remote?'checked':''}> Remote only</label></div>
<div class="row section"><button type="submit" id="li-search" class="primary" ${running?'disabled':''}>${running?'Searching…':'Search LinkedIn'}</button><button type="button" id="li-rematch" ${running||!jobs.length?'disabled':''}>Re-match saved results</button><span id="li-open">${link(linkedinSearchUrl(c),'Open this search on LinkedIn ↗')}</span></div></form>
<p id="li-status" role="status" aria-live="polite">${esc(running?data.activity.message:data.message||'Enter a role and location, then search.')}</p>
${data.status==='error'||data.status==='interrupted'?`<p class="notice">The last request did not finish. Results below belong to the previous saved search: ${esc(data.results_config?.query||'none')} · ${esc(data.results_config?.location||'')}. No jobs were marked closed.</p>`:''}
${data.pagination?`<p class="small muted">${esc(data.pagination.pages_fetched)} pages read / ${esc(({page_limit:'Page limit reached',result_limit:'Results cap reached',end_of_results:'End of public results',no_new_jobs:'Stopped: page contained no new jobs',time_limit:'Search time limit reached',request_failed:'Stopped: request failed; partial results saved'})[data.pagination.stop_reason]||data.pagination.stop_reason)}</p>`:''}
${arr(data.warnings).length?`<details class="section"><summary>Search coverage notes</summary><ul>${list(data.warnings)}</ul></details>`:''}
<div class="toolbar"><label>Show results<select id="li-view"><option value="all" ${linkedinView==='all'?'selected':''}>All fetched results</option><option value="match" ${linkedinView==='match'?'selected':''}>Keyword matches</option><option value="unknown" ${linkedinView==='unknown'?'selected':''}>Uncertain — card only</option><option value="no_match" ${linkedinView==='no_match'?'selected':''}>No keyword match</option><option value="excluded" ${linkedinView==='excluded'?'selected':''}>Excluded titles</option></select></label><p class="small muted">${shown.length} shown · ${matches} keyword matches / ${jobs.length} fetched · Snapshot ${esc(formatDate(data.checked_at))}</p></div>
<div class="grid">${shown.length?shown.map(j=>`<article class="card"><p class="company">${esc(j.company)}</p><h3>${link(j.url,j.title)}</h3><p class="small muted">${esc(j.location)} · Posted ${esc(j.posted_at||'unknown')}</p><div class="chips"><span class="chip ${j.match_status==='match'?'good':'warn'}">${esc({match:'Keyword match',unknown:'Uncertain',no_match:'No keyword match',excluded:'Excluded title'}[j.match_status]||'Snapshot')}</span><span class="chip">${esc(j.coverage)}</span></div><p><strong>Found:</strong> ${esc(j.matched?.join(', ')||'No configured terms found')}</p>${j.not_found?.length?`<p class="small muted">Not found in scanned text: ${esc(j.not_found.join(', '))}${j.coverage==='Card only'?'. Description was not scanned; this is not evidence that the skills are absent.':''}</p>`:''}${j.excluded?.length?`<p class="small muted">Excluded title terms: ${esc(j.excluded.join(', '))}</p>`:''}<p class="small muted">${esc(j.detail_status)} · LinkedIn snapshot, not employer verification.</p><div class="row"><button data-li-track="${esc(j.id)}">Track / open saved job</button>${link(j.url,'View original ↗')}</div></article>`).join(''):'<p class="empty">No results in this view. Run a search or choose another result filter.</p>'}</div>
<p class="small muted section">Tracked snapshots are available with “Listed roles only” and “Resume-reviewed only” unchecked in Job radar. Existing notes and application status survive repeated imports. Searches stop on login gates or rate limits; results already saved stay available.</p>`;
for(const key of ['query','location','keywords','exclude'])$('#li-'+key).oninput=e=>{c[key]=e.target.value;$('#li-open').innerHTML=link(linkedinSearchUrl(c),'Open this search on LinkedIn ↗')};
for(const key of ['posted','mode','limit','pages'])$('#li-'+key).onchange=e=>{c[key]=['limit','pages'].includes(key)?Number(e.target.value):e.target.value;$('#li-open').innerHTML=link(linkedinSearchUrl(c),'Open this search on LinkedIn ↗')};
$('#li-remote').onchange=e=>{c.remote=e.target.checked;$('#li-open').innerHTML=link(linkedinSearchUrl(c),'Open this search on LinkedIn ↗')};
$('#li-view').onchange=e=>{linkedinView=e.target.value;renderLinkedin()};
$('#linkedin-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/linkedin/search',{...c});state.linkedin=await api('/api/linkedin/status');renderLinkedin();pollLinkedin()}catch(error){toast(error.message)}};
$('#li-rematch').onclick=async()=>{try{await api('/api/linkedin/rematch',{...c});state.linkedin=await api('/api/linkedin/status');renderLinkedin()}catch(error){toast(error.message)}};
document.querySelectorAll('[data-li-track]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await api('/api/linkedin/track',{id:b.dataset.liTrack});await load();openJob(result.id);toast(result.existing?'Opened the existing tracked job':'Saved LinkedIn snapshot to Job radar')}catch(error){toast(error.message)}finally{b.disabled=false}});
if(running)pollLinkedin();
}
function pollLinkedin(){if(linkedinPoll)return;linkedinPoll=setInterval(async()=>{try{state.linkedin=await api('/api/linkedin/status');if(!state.linkedin.activity.running){clearInterval(linkedinPoll);linkedinPoll=null;if(tab==='linkedin')renderLinkedin();toast(state.linkedin.message)}else if(tab==='linkedin'&&$('#li-status'))$('#li-status').textContent=state.linkedin.activity.message}catch(e){clearInterval(linkedinPoll);linkedinPoll=null;toast('Could not check LinkedIn search progress. Reload to recover the saved state.')}},1500)}
